public static class MediaEndpoints{public static IEndpointRouteBuilder MapMediaEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/content/media").WithTags("Content Media").RequireAuthorization();g.MapGet("/",async(int? pageNumber,int? pageSize,string? search,string? contentType,IQueryDispatcher d,CancellationToken ct)=>EndpointResults.FromPaged(await d.DispatchAsync(new GetMediaQuery(PageRequest.Create(pageNumber??1,pageSize??25),search,contentType),ct))).RequireScope(ContentScopeNames.View);g.MapPost("/register",async(RegisterMediaRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new RegisterMediaCommand(r.StorageFileId,r.FileName,r.ContentType,r.AltText,r.Caption,r.MetadataJson,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.MediaUpload);g.MapPatch("/{id:guid}",async(Guid id,UpdateMediaMetadataRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new UpdateMediaMetadataCommand(id,r.AltText,r.Caption,r.MetadataJson,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Edit);g.MapDelete("/{id:guid}",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new DeleteMediaCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.MediaDelete);g.MapPost("/upload",UploadAsync).DisableAntiforgery().RequireScope(ContentScopeNames.MediaUpload);return app;}
private static async Task<IResult> UploadAsync(HttpRequest request,HttpContext h,IHttpClientFactory clients,ICommandDispatcher dispatcher,CancellationToken ct){if(!request.HasFormContentType)return Results.Problem("La carga debe ser multipart/form-data.",statusCode:400);var form=await request.ReadFormAsync(ct);var file=form.Files.GetFile("file")??form.Files.FirstOrDefault();if(file is null)return Results.Problem("Debe adjuntar un archivo.",statusCode:400);using var content=new MultipartFormDataContent();await using var stream=file.OpenReadStream();var streamContent=new StreamContent(stream);streamContent.Headers.ContentType=new MediaTypeHeaderValue(string.IsNullOrWhiteSpace(file.ContentType)?"application/octet-stream":file.ContentType);content.Add(streamContent,"file",file.FileName);content.Add(new StringContent("DholeContentService"),"sourceService");content.Add(new StringContent("CmsMedia"),"entityType");content.Add(new StringContent(Guid.NewGuid().ToString()),"entityId");var metadata=form["metadataJson"].ToString();if(!string.IsNullOrWhiteSpace(metadata))content.Add(new StringContent(metadata),"metadataJson");var client=clients.CreateClient("DholeStorage");using var outbound=new HttpRequestMessage(HttpMethod.Post,"api/v1/storage/files"){Content=content};var auth=h.Request.Headers.Authorization.ToString();if(!string.IsNullOrWhiteSpace(auth))outbound.Headers.TryAddWithoutValidation("Authorization",auth);using var response=await client.SendAsync(outbound,ct);var json=await response.Content.ReadAsStringAsync(ct);if(!response.IsSuccessStatusCode)return Results.Content(json,"application/problem+json",statusCode:(int)response.StatusCode);using var doc=JsonDocument.Parse(json);var root=doc.RootElement;Guid storageId=default;if(root.TryGetProperty("id",out var direct))Guid.TryParse(direct.ToString(),out storageId);if(storageId==Guid.Empty&&root.TryGetProperty("data",out var data)&&data.TryGetProperty("id",out var nested))Guid.TryParse(nested.ToString(),out storageId);if(storageId==Guid.Empty)return Results.Problem("Storage no devolvió un id de archivo válido.",statusCode:502);var result=await dispatcher.DispatchAsync(new RegisterMediaCommand(storageId,file.FileName,string.IsNullOrWhiteSpace(file.ContentType)?"application/octet-stream":file.ContentType,Null(form["altText"].ToString()),Null(form["caption"].ToString()),Null(metadata),h.GetCurrentUserId()),ct);return EndpointResults.FromResult(result,h);}private static string? Null(string value)=>string.IsNullOrWhiteSpace(value)?null:value;}
